"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 pilot of the front-end-error ablation on dev (docs/iterations.md, 2026-11-16; local systems only, no API).

Question: does a listening model stay right when the detector reports a ring that never happened, while text-only
systems are misled? The design was fixed in the log before running:
- every dev decision point whose 8 s window holds no real phone, doorbell or knock clip gets one false "phone"
  detection ending 0.3-1.5 s before the line starts (or before the point when no line), 1.5-3.0 s long, clipped to
  the window (points with less than 0.5 s of room before the line are skipped and counted);
- its confidence is drawn from the dev false alarms: phone, doorbell or knock detections inside the windows of the
  no-event R-hear version (seed 0);
- it enters every input that carries detector output: the sound list (situation text, B1's inputs, the time-since
  features) and, for the feature heads, the detector frames (phone frames raised to the confidence over the
  interval); the audio is unchanged;
- systems at their frozen dev thresholds or setting: ours (L1), T, L2, L3, B1-strong; clean = the stored dev outputs.
Outputs: data/p1v4/runs/inject_pilot/ (injections, scores, decisions, the copied and changed feature files) and
results/main_v04/inject_pilot_dev.json.
usage: .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_inject_pilot.py
"""
import json
import os
import random
import shutil
import sys

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_score as S  # noqa: E402

R = "data/p1v4/runs"
OUT = f"{R}/inject_pilot"
EVENT = ("phone", "doorbell", "knock")
SEED = 0


def keyed(d):
    return {(k.split("|")[0], k.split("|")[1], int(k.split("|")[2])): v for k, v in d.items()}


def false_alarm_confidences(rows):
    snd = json.load(open(f"{C.FEATS}/dev_sounds.json"))
    out = []
    for r in rows:
        if r["part"] == "r_hear" and r["version"] == "2":
            for p in r["points"]:
                t = p["t"]
                out += [s[3] for s in snd.get(f"{r['unit']}|{r['version']}|{p['k']}", [])
                        if s[0] in EVENT and s[2] > t - D.WIN_S and s[1] < t]
    return sorted(out)


def injections(rows):
    rng = random.Random(SEED)
    conf = false_alarm_confidences(rows)
    inj, skipped = {}, 0
    for r in rows:
        src = {s["id"]: s for s in r["sources"]}
        for p in r["points"]:
            t = p["t"]
            if any(c in EVENT for c, _, _ in D.window_events(r, t)):
                continue
            w0 = t - D.WIN_S
            ls = src[p["line"]]["start"] if p.get("line") else t
            s1 = ls - rng.uniform(0.3, 1.5)
            s0 = max(s1 - rng.uniform(1.5, 3.0), w0 + 0.01)
            c = rng.choice(conf)
            if s1 - s0 < 0.5:
                skipped += 1
                continue
            inj[f"{r['unit']}|{r['version']}|{p['k']}"] = ["phone", round(s0, 2), round(s1, 2), round(float(c), 3)]
    return inj, skipped, conf


def patch_context(inj):
    base = C.Context

    class Injected(base):
        def point(self, r, k):
            tr, sc, tags, snd = super().point(r, k)
            e = inj.get(self.pid(r, k))
            if e:
                snd = sorted(list(snd) + [tuple(e)], key=lambda s: (s[1], s[0]))
            return tr, sc, tags, snd

    C.Context = Injected
    return base


def injected_feature_dir(rows, inj):
    """A copy of the dev window-detector files with the phone frames raised over each injected interval."""
    d = f"{OUT}/feats"
    os.makedirs(d, exist_ok=True)
    for f in ("sed_win_dev_ids.json", "sed_win_dev_emb.npy", "voxturn_dev.json"):
        shutil.copy(f"{C.FEATS}/{f}", f"{d}/{f}")
    ids = json.load(open(f"{C.FEATS}/sed_win_dev_ids.json"))
    frames = np.load(f"{C.FEATS}/sed_win_dev_frames.npy")
    times = {f"{r['unit']}|{r['version']}|{p['k']}": p["t"] for r in rows for p in r["points"]}
    ph = D.DET_CLASSES.index("phone")
    for i, pid in enumerate(ids):
        e = inj.get(pid)
        if e:
            w0 = times[pid] - D.WIN_S
            a, b = int(np.floor((e[1] - w0) * 100)), int(np.floor((e[2] - w0) * 100))
            frames[i, a:b + 1, ph] = np.maximum(frames[i, a:b + 1, ph], e[3])
    np.save(f"{d}/sed_win_dev_frames.npy", frames)
    return d


def head_scores(L2, system, device="cuda"):
    import torch
    import torch.nn as nn
    ck = torch.load(f"{R}/{system}/{system}.pt", weights_only=False)            # our own file (numpy means)
    ids, X = L2.load_X("dev", system)
    X = ((X - ck["mu"]) / ck["sd"]).astype(np.float32)
    dim = X.shape[1]
    net = nn.Linear(dim, 2) if ck["kind"] == "lr" else nn.Sequential(nn.Linear(dim, 256), nn.GELU(), nn.Dropout(0.2),
                                                                     nn.Linear(256, 2))
    net.load_state_dict(ck["state"])
    return L2.scores_of(net.to(device).eval(), X, ids, device)


def summary(rows, dec, groups):
    T = S.unit_table(rows, dec, groups)
    m = S.metrics(T)
    rh = {}
    for r in rows:
        if r["part"] == "r_hear" and r["unit"] not in S.excluded_units():
            for p in r["points"]:
                d = dec.get((r["unit"], r["version"], p["k"]), {})
                rh.setdefault(r["version"], []).append(d.get("R") == p["gold"]["R"])
    return {"primary": m["primary"], "parts": m["parts"], "floors": m["floors"],
            "r_hear_versions": {v: float(np.mean(x)) for v, x in sorted(rh.items())}}


def main():
    import torch
    D.gpu_guard()
    os.makedirs(OUT, exist_ok=True)
    rows = D.load_rows("dev")
    groups = S.load_groups("dev")
    inj, skipped, conf = injections(rows)
    json.dump(inj, open(f"{OUT}/injections.json", "w"))
    print(f"injected {len(inj)} points, skipped {skipped}; false-alarm confidences n={len(conf)}, "
          f"median {np.median(conf):.2f}", flush=True)
    rep = json.load(open("results/main_v04/dev_report.json"))["systems"]
    th = {n: (rep[n]["operating_point"]["th_s"], rep[n]["operating_point"]["th_r"]) for n in ("L1", "L2", "L3", "T")}
    clean = {"L1": f"{R}/l1/scores_dev.json", "L2": f"{R}/l2/scores_dev.json", "L3": f"{R}/l3/scores_dev.json",
             "T": f"{R}/t/scores_dev.json"}
    original = patch_context(inj)
    new = {}
    try:
        import p1v4_l2 as L2
        L2.FEATS = injected_feature_dir(rows, inj)            # features read and written in the pilot's copy
        L2.features("dev")
        new["T"], new["L2"] = head_scores(L2, "t"), head_scores(L2, "l2")
        import p1v4_l3 as L3
        ck = torch.load(f"{R}/l3/l3.pt", weights_only=False)                   # our own file (numpy means)
        wins, _, y, X, _, _ = L3.data("dev", ck["mu"], ck["sd"])
        net = L3.Net(X.shape[1]).cuda()
        net.load_state_dict(ck["state"])
        new["L3"] = L3.score(net, wins, X, y)
        import p1v4_b1 as B1
        chosen = json.load(open(f"{R}/b1/b1_dev.json"))["setting"]
        pts = B1.point_inputs(rows, C.Context("dev"), json.load(open(f"{R}/b1/mined_phrases.json")))
        one = B1.Grid(np.array([[B1.GRID[n].index(chosen[n]) for n in B1.GRID]], np.int16))
        b1_dec = B1.decisions_for(pts, one, 0)
        import p1v4_l1 as L1
        ex, _ = L1.examples("dev")
        model = L1.build()
        L1.load_new_state(model, torch.load(f"{R}/l1/l1_new.pt", weights_only=True))
        new["L1"] = L1.score(model, ex)
    finally:
        C.Context = original
    for n, sc in new.items():
        json.dump({"|".join(map(str, k)): v for k, v in sc.items()}, open(f"{OUT}/scores_{n}.json", "w"))
    json.dump({"|".join(map(str, k)): v for k, v in b1_dec.items()}, open(f"{OUT}/decisions_B1.json", "w"))
    res = {"injected_points": len(inj), "skipped": skipped, "false_alarm_conf_median": float(np.median(conf))}
    for n in ("L1", "L3", "L2", "T"):
        c = summary(rows, S.decide(keyed(json.load(open(clean[n]))), *th[n]), groups)
        i = summary(rows, S.decide(new[n], *th[n]), groups)
        res[n] = {"clean": c, "injected": i, "drop_primary": c["primary"] - i["primary"]}
    c = summary(rows, keyed(json.load(open(f"{R}/b1/decisions_dev.json"))), groups)
    i = summary(rows, b1_dec, groups)
    res["B1-strong"] = {"clean": c, "injected": i, "drop_primary": c["primary"] - i["primary"]}
    json.dump(res, open("results/main_v04/inject_pilot_dev.json", "w"), indent=1)
    for n in ("L1", "L3", "L2", "T", "B1-strong"):
        x = res[n]
        print(f"{n:10s} five-part mean {x['clean']['primary']:.3f} -> {x['injected']['primary']:.3f} "
              f"(drop {x['drop_primary']:+.3f}); R-hear v1/v2/v3 "
              + " ".join(f"{x['clean']['r_hear_versions'][v]:.2f}->{x['injected']['r_hear_versions'][v]:.2f}"
                         for v in ("1", "2", "3"))
              + "; parts " + " ".join(f"{p}:{x['clean']['parts'][p]:.2f}->{x['injected']['parts'][p]:.2f}"
                                      for p in S.PARTS), flush=True)


if __name__ == "__main__":
    main()
